-- Tidy what the page prints, for the rows already stored (ingest/places.py, ingest/names.py).
--
-- One place, one spelling: the register writes "Bengaluru Urban", the grants lists
-- "Bangalore", and Karnataka's districts line read "Bengaluru Urban 17 · Bangalore 11 ·
-- Bengaluru 4". Only a spelling or a district that is the city under its official name
-- is folded; a state printed where a city belongs is cleared.
--
-- Register names in capitals recased, so 175 of 607 rows stop shouting beside the rest.
-- A name with any lower-case letter is the company's own spelling and is not touched.
-- Each update names the old value, so a row the nightly has already rewritten is left.
--
-- The entity note said "the name carries a legal suffix" under names that carry none,
-- because the suffix was on another source's copy of the name.

UPDATE companies SET city = CASE lower(trim(city))
    WHEN 'bangalore' THEN 'Bengaluru'
    WHEN 'bengaluru urban' THEN 'Bengaluru'
    WHEN 'bhubaneshwar' THEN 'Bhubaneswar'
    WHEN 'trivandrum' THEN 'Thiruvananthapuram'
    WHEN 'kanpur nagar' THEN 'Kanpur'
    WHEN 'mumbai suburban' THEN 'Mumbai'
    WHEN 'south eastdelhi' THEN 'South East Delhi'
    WHEN 'jammu, j & k' THEN 'Jammu'
  END
WHERE lower(trim(city)) IN ('bangalore', 'bengaluru urban', 'bhubaneshwar', 'trivandrum', 'kanpur nagar', 'mumbai suburban', 'south eastdelhi', 'jammu, j & k');
UPDATE companies SET city = NULL WHERE lower(trim(city)) IN ('jharkhand');

UPDATE companies SET entity_note = 'a source lists it with a legal suffix' WHERE entity_note = 'the name carries a legal suffix';

